.ends SUB_1

.control
save all @m.xm1.msky130_fd_pr__nfet_01v8[id] @m.xm2.msky130_fd_pr__nfet_01v8[id] @m.xm6t.msky130_fd_pr__nfet_01v8[id]

* 1. DC Operating Point analysis
op
let iss_op = @m.xm6t.msky130_fd_pr__nfet_01v8[id]
let id1_op = @m.xm1.msky130_fd_pr__nfet_01v8[id]
let id2_op = @m.xm2.msky130_fd_pr__nfet_01v8[id]
print iss_op id1_op id2_op

* 2. DC Sweep corresponding to Baker Ex 22.1 / Fig 22.3
dc VI1 0.4 1.4 0.002
let id1 = @m.xm1.msky130_fd_pr__nfet_01v8[id]
let id2 = @m.xm2.msky130_fd_pr__nfet_01v8[id]
let iss = id1 + id2
let diff_id = id1 - id2

* Measure balanced branch current and tail current at vI1 = 0.9 V
meas dc iss_balanced find iss at=0.9
meas dc id1_balanced find id1 at=0.9
meas dc id2_balanced find id2 at=0.9

* Measure maximum and minimum steering voltages (at 95% of full tail current)
meas dc vi1_max when id1=0.95*iss_balanced rise=1
meas dc vi1_min when id1=0.05*iss_balanced fall=1

* 3. AC analysis for small-signal gm measurement
alter VI1 dc=0.9
ac dec 10 1k 100k
let gm_meas = mag(i(VI1)) / (2 * PI * 1k * 1e-15 + 1e-20)
print @m.xm1.msky130_fd_pr__nfet_01v8[gm]

quit
.endc
.end

